 if(mode==='completion-collision'){const copied=one('loop-completion-copy','completion_records','id','original-loop-record');expect(copied.original.cells.owner_id).toEqual({type:'text',value:'B'});expect(ids(copied)).toEqual(['session-B']);expect(ids(one('loops','completion_records','id','original-loop-record'))).toEqual(['session-A']);}
