it.each(['match','collision','empty','uninterpreted'] as const)('retains every original KSwarm state/history/meta entity without inferring same-name session authority: %s',async mode=>{
 const f=await closureFixture(false,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,mode),api=await import('../../../src/runtime/verification/installed-metadata-closure.js');
 try{const handle=await closureCall(api,'collectInstalledMetadataClosure',f.lifetime,f.owner,f.token,f.source),facts=closureCall(api,'readInstalledMetadataClosure',f.lifetime,handle);
  expect(f.kswarmRows).toHaveLength(mode==='collision'?2:1);
  for(const source of f.kswarmRows){
   const all=facts.entities.filter((v:any)=>v.sourceId===source.sourceId&&v.family==='kswarm');
   expect(all).toHaveLength(Object.values(source.original).reduce((sum,rows)=>sum+rows.length,0));
   expect(facts.sources).toContainEqual(expect.objectContaining({sourceId:source.sourceId,family:'kswarm',sessions:[]}));
   for(const [table,rows] of Object.entries(source.original)){
    const captured=all.filter((v:any)=>v.original.table===table);expect(captured,table).toHaveLength(rows.length);
    for(const raw of rows){
     const entity=captured.find((v:any)=>v.original.rowid===String(raw.original_rowid));expect(entity,table+' '+raw.original_rowid).toBeDefined();
     expect(entity.recordKind).toBe('kswarm-row');expect(entity.originalRecordKey).toBe(JSON.stringify([table,String(raw.original_rowid)]));expect(entity.origin).toEqual({sourceId:source.sourceId,path:table+'['+raw.original_rowid+']'});expect(entity.sessions).toEqual([]);
     const expected=Object.fromEntries(Object.entries(raw).filter(([column])=>column!=='original_rowid')),classes=source.classes[table].find(v=>v.original_rowid===raw.original_rowid);
     expect(Object.keys(entity.original.record).sort()).toEqual(Object.keys(expected).sort());
     for(const [column,value] of Object.entries(expected)){const cell=entity.original.record[column],kind=classes[column];expect(cell.type).toBe(kind);const decoded=kind==='integer'?BigInt(cell.value):kind==='real'?Buffer.from(cell.value,'hex').readDoubleBE():kind==='blob'?Buffer.from(cell.value,'base64'):kind==='null'?null:cell.value;expect(decoded,table+'.'+column).toEqual(value);}
     expect(facts.mapper.events).toContainEqual({kind:'family-fact',family:'kswarm',fact:entity.original});
     expect(entity.unresolved).toContainEqual(expect.objectContaining({reason:table==='state_meta'?'kswarm-metadata-semantics-required':'kswarm-session-binding-required'}));
     expect(entity.dependencies).toHaveLength(entity.original.references.length);
     for(const [i,ref] of entity.original.references.entries())expect(entity.dependencies[i]).toEqual({namespace:ref.domain,id:JSON.stringify(ref.value),origin:{sourceId:source.sourceId,path:entity.origin.path+'.references['+i+']'},scope:{...ref,resolution:'declaration-only'}});
    }
   }
   const collections=new Set([...source.original.state_entities,...source.original.state_entity_history].map(row=>row.collection));expect(collections.size).toBe(mode==='empty'?0:8);
   if(mode!=='empty'){expect(source.original.state_entity_history.some(row=>row.collection==='workflowProposal'&&row.entity_key==='deleted-proposal')).toBe(true);expect(source.original.state_entities.some(row=>row.collection==='workflowProposal')).toBe(false);expect(source.original.state_entities.find(row=>row.collection==='board').state_json.length).toBeGreaterThan(64*1024);}
  }
  if(mode==='uninterpreted'){const board=facts.entities.find((v:any)=>v.sourceId==='kswarm-original'&&v.original.table==='state_entities'&&v.original.record.collection.value==='board');expect(board.original.references.every((v:any)=>v.referenceState==='uninterpreted')).toBe(true);}
  expect(facts.unresolved.some((v:any)=>v.reason==='legacy-inventory-required')).toBe(true);expect(facts).not.toHaveProperty('ready');await closureCall(api,'checkInstalledMetadataClosure',f.lifetime,handle);
 }finally{await f.close();}
},15000);
